// The page guides behind each page header's info button. Each guide is
// src/help/<slug>.md; its screenshots are public/help/<slug>*.png,
// regenerated by `npm run help:screenshots`.

export interface Guide {
  slug: string
  title: string
  /** The console page the guide explains, for the way back. */
  path: string
}

export const GUIDES = [
  { slug: 'dashboard', title: 'Dashboard', path: '/dashboard' },
  { slug: 'customers', title: 'Customers', path: '/customers' },
  { slug: 'payments', title: 'Payments', path: '/payments' },
  { slug: 'orders', title: 'Orders', path: '/orders' },
  { slug: 'refunds', title: 'Refunds', path: '/refunds' },
  { slug: 'disputes', title: 'Disputes', path: '/disputes' },
  { slug: 'withdrawals', title: 'Withdrawals', path: '/withdrawals' },
  { slug: 'ledger-accounts', title: 'Ledger accounts', path: '/ledger/accounts' },
  { slug: 'trial-balance', title: 'Trial balance', path: '/ledger/trial-balance' },
  { slug: 'ledger-checks', title: 'Ledger checks', path: '/ledger/checks' },
  { slug: 'recon', title: 'Reconciliation', path: '/recon' },
  { slug: 'providers', title: 'Providers', path: '/providers' },
  { slug: 'reports', title: 'Reports', path: '/reports' },
  { slug: 'products', title: 'Products', path: '/products' },
  { slug: 'wallet-types', title: 'Wallet types', path: '/wallet-types' },
  { slug: 'audit', title: 'Audit log', path: '/audit' },
  { slug: 'settings', title: 'Settings', path: '/settings' },
] as const satisfies readonly Guide[]

export type GuideSlug = (typeof GUIDES)[number]['slug']

const content = import.meta.glob<string>('./*.md', { query: '?raw', import: 'default', eager: true })

/**
 * guideMarkdown returns a guide's text with its screenshots pointed at
 * public/help/ under the console's base path. Guides name an image by file
 * alone — ![…](payments.png) — so they read the same in an editor.
 */
export function guideMarkdown(slug: string): string | undefined {
  const raw = content[`./${slug}.md`]
  if (raw === undefined) return undefined
  return raw.replace(/\]\(([\w-]+\.png)\)/g, `](${import.meta.env.BASE_URL}help/$1)`)
}
